var e=[{code:`trial`,label:`Trial`,days:7,color:`yellow`},{code:`monthly`,label:`Monthly`,days:30,color:`blue`},{code:`quarterly`,label:`Quarterly`,days:90,color:`blue`},{code:`yearly`,label:`Yearly`,days:365,color:`green`}],t=e=>{if(!e)return null;let t=new Date;t.setHours(0,0,0,0);let n=new Date(e);return n.setHours(0,0,0,0),Math.ceil((n-t)/864e5)},n=(e,n)=>{if(e===`inactive`)return{label:`Inactive`,color:`gray`};if(!n)return{label:`No Expiry`,color:`gray`};let r=t(n);return r<0?{label:`Expired`,color:`red`}:r===0?{label:`Expires Today`,color:`orange`}:r<=7?{label:`${r}d left`,color:`orange`}:r<=30?{label:`${r}d left`,color:`yellow`}:{label:`${r}d left`,color:`green`}};export{t as n,n as r,e as t};